import{_ as o,a0 as t,w as r,s as d,ao as l,I as a,x as n,a1 as p,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"在 Linux 上使用 groff -me 格式化你的学术论文 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上使用 groff -me 格式化你的学术论文 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上使用 groff -me 格式化你的学术论文 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上使用 groff -me 格式化你的学术论文 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180220 How to format academic papers on Linux with groff -me","title":"在 Linux 上使用 groff -me 格式化你的学术论文","tag":"201805","desc":""},"relativePath":"201805/20180220 How to format academic papers on Linux with groff -me.md","filePath":"[post].md"}'),c={name:"201805/20180220 How to format academic papers on Linux with groff -me.md"};function f(u,s,h,g,m,b){const e=t("Link");return r(),d("div",null,[s[35]||(s[35]=l('<h1 id="在-linux-上使用-groff-me-格式化你的学术论文" tabindex="-1">在 Linux 上使用 groff -me 格式化你的学术论文 <a class="header-anchor" href="#在-linux-上使用-groff-me-格式化你的学术论文" aria-label="Permalink to “在 Linux 上使用 groff -me 格式化你的学术论文”">​</a></h1><blockquote><p>学习用简单的宏为你的课程论文添加脚注、引用、子标题及其它格式。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/life_paperclips.png?itok=j48op49T" alt=""></p><p>当我在 1993 年发现 Linux 时，我还是一名本科生。我很兴奋在我的宿舍里拥有 Unix 系统的强大功能，但是尽管它有很多功能，但 Linux 却缺乏应用程序。像 LibreOffice 和 OpenOffice 这样的文字处理程序还需要几年的时间才出现。如果你想使用文字处理器，你可能会将你的系统引导到 MS-DOS 中，并使用 WordPerfect、共享软件 GalaxyWrite 或类似的程序。</p><p>这就是我的方法，因为我需要为我的课程写论文，但我更喜欢呆在 Linux 中。我从我们的 “大 Unix” 校园计算机实验室得知，Unix 系统提供了一组文本格式化的程序 <code>nroff</code> 和 <code>troff </code> ，它们是同一系统的不同接口：<code>nroff</code> 生成纯文本输出，适用于屏幕或行式打印机，而 <code>troff</code> 产生非常优美的输出，通常用于在激光打印机上打印。</p>',5)),a("p",null,[s[1]||(s[1]=n("在 Linux 上，",-1)),s[2]||(s[2]=a("code",null,"nroff",-1)),s[3]||(s[3]=n(" 和 ",-1)),s[4]||(s[4]=a("code",null,"troff",-1)),s[5]||(s[5]=n(" 被合并为 GNU troff，通常被称为 ",-1)),p(e,{href:"https://www.gnu.org/software/groff/"},{default:i(()=>[...s[0]||(s[0]=[n("groff",-1)])]),_:1}),s[6]||(s[6]=n("。 我很高兴看到早期的 Linux 发行版中包含了某个版本的 groff，因此我着手学习如何使用它来编写课程论文。 我学到的第一个宏集是 ",-1)),s[7]||(s[7]=a("code",null,"-me",-1)),s[8]||(s[8]=n(" 宏包，一个简单易学的宏集。",-1))]),s[36]||(s[36]=l(`<p>关于 <code>groff</code> ，首先要了解的是它根据一组宏来处理和格式化文本。宏通常是个两个字符的命令，它自己设置在一行上，并带有一个引导点。宏可能包含一个或多个选项。当 <code>groff</code> 在处理文档时遇到这些宏中的一个时，它会自动对文本进行格式化。</p><p>下面，我将分享使用 <code>groff -me</code> 编写课程论文等简单文档的基础知识。 我不会深入细节进行讨论，比如如何创建嵌套列表，保存和显示，以及使用表格和数字。</p><h3 id="段落" tabindex="-1">段落 <a class="header-anchor" href="#段落" aria-label="Permalink to “段落”">​</a></h3><p>让我们从一个简单的例子开始，在几乎所有类型的文档中都可以看到：段落。段落可以格式化为首行缩进或不缩进（即，与左边齐平）。 包括学术论文，杂志，期刊和书籍在内的许多印刷文档都使用了这两种类型的组合，其中文档或章节中的第一个（主要）段落左侧对齐，而所有其他（常规）的段落缩进。 在 <code>groff -me</code>中，您可以使用两种段落类型：前导段落（<code>.lp</code>）和常规段落（<code>.pp</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.lp</span></span>
<span class="line"><span>This is the first paragraph.</span></span>
<span class="line"><span>.pp</span></span>
<span class="line"><span>This is a standard paragraph.</span></span></code></pre></div><h3 id="文本格式" tabindex="-1">文本格式 <a class="header-anchor" href="#文本格式" aria-label="Permalink to “文本格式”">​</a></h3><p>用粗体格式化文本的宏是 <code>.b</code>，斜体格式是 <code>.i</code> 。 如果您将 <code>.b</code> 或 <code>.i</code> 放在一行上，则后面的所有文本将以粗体或斜体显示。 但更有可能你只是想用粗体或斜体来表示一个或几个词。 要将一个词加粗或斜体，将该单词放在与 <code>.b</code> 或 <code>.i</code> 相同的行上作为选项。 要用粗体或斜体格式化多个单词，请将文字用引号引起来。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.pp</span></span>
<span class="line"><span>You can do basic formatting such as</span></span>
<span class="line"><span>.i italics</span></span>
<span class="line"><span>or</span></span>
<span class="line"><span>.b &quot;bold text.&quot;</span></span></code></pre></div><p>在上面的例子中，粗体文本结尾的句点也是粗体。 在大多数情况下，这不是你想要的。 只要文字是粗体字，而不是后面的句点也是粗体字。 要获得您想要的效果，您可以向 <code>.b</code> 或 <code>.i</code> 添加第二个参数，以指示以粗体或斜体显示的文本后面跟着的任意文本以正常类型显示。 您可以这样做，以确保尾随句点不会以粗体显示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.pp</span></span>
<span class="line"><span>You can do basic formatting such as</span></span>
<span class="line"><span>.i italics</span></span>
<span class="line"><span>or</span></span>
<span class="line"><span>.b &quot;bold text&quot; .</span></span></code></pre></div><h3 id="列表" tabindex="-1">列表 <a class="header-anchor" href="#列表" aria-label="Permalink to “列表”">​</a></h3><p>使用 <code>groff -me</code>，您可以创建两种类型的列表：无序列表（<code>.bu</code>）和有序列表（<code>.np</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.pp</span></span>
<span class="line"><span>Bullet lists are easy to make:</span></span>
<span class="line"><span>.bu</span></span>
<span class="line"><span>Apple</span></span>
<span class="line"><span>.bu</span></span>
<span class="line"><span>Banana</span></span>
<span class="line"><span>.bu</span></span>
<span class="line"><span>Pineapple</span></span>
<span class="line"><span>.pp</span></span>
<span class="line"><span>Numbered lists are as easy as:</span></span>
<span class="line"><span>.np</span></span>
<span class="line"><span>One</span></span>
<span class="line"><span>.np</span></span>
<span class="line"><span>Two</span></span>
<span class="line"><span>.np</span></span>
<span class="line"><span>Three</span></span>
<span class="line"><span>.pp</span></span>
<span class="line"><span>Note that numbered lists will reset at the next pp or lp.</span></span></code></pre></div><h3 id="副标题" tabindex="-1">副标题 <a class="header-anchor" href="#副标题" aria-label="Permalink to “副标题”">​</a></h3><p>如果你正在写一篇长论文，你可能想把你的内容分成几部分。使用 <code>groff -me</code>，您可以创建编号的标题（<code>.sh</code>） 和未编号的标题 （<code>.uh</code>）。在这两种方法中，将节标题作为参数括起来。对于编号的标题，您还需要提供标题级别 <code>:1</code> 将给出一个一级标题(例如，<code>1</code>)。同样，<code>2</code> 和 <code>3</code> 将给出第二和第三级标题，如 <code>2.1</code> 或 <code>3.1.1</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.uh Introduction</span></span>
<span class="line"><span>.pp</span></span>
<span class="line"><span>Provide one or two paragraphs to describe the work</span></span>
<span class="line"><span>and why it is important.</span></span>
<span class="line"><span>.sh 1 &quot;Method and Tools&quot;</span></span>
<span class="line"><span>.pp</span></span>
<span class="line"><span>Provide a few paragraphs to describe how you</span></span>
<span class="line"><span>did the research, including what equipment you used</span></span></code></pre></div><h3 id="智能引号和块引号" tabindex="-1">智能引号和块引号 <a class="header-anchor" href="#智能引号和块引号" aria-label="Permalink to “智能引号和块引号”">​</a></h3><p>在任何学术论文中，引用他人的工作作为证据都是正常的。如果你引用一个简短的引用来突出一个关键信息，你可以在你的文本周围键入引号。但是 groff 不会自动将你的引用转换成现代文字处理系统所使用的“智能”或“卷曲”引用。要在 <code>groff -me</code> 中创建它们，插入一个内联宏来创建左引号（<code>\\*(lq</code>）和右引号（<code>\\*(rq</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.pp</span></span>
<span class="line"><span>Christine Peterson coined the phrase \\*(lqopen source.\\*(rq</span></span></code></pre></div><p><code>groff -me</code> 中还有一个快捷方式来创建这些引号（<code>.q</code>），我发现它更易于使用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.pp</span></span>
<span class="line"><span>Christine Peterson coined the phrase</span></span>
<span class="line"><span>.q &quot;open source.&quot;</span></span></code></pre></div><p>如果引用的是跨越几行的较长的引用，则需要使用一个块引用。为此，在引用的开头和结尾插入块引用宏（<code>.(q</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.pp</span></span>
<span class="line"><span>Christine Peterson recently wrote about open source:</span></span>
<span class="line"><span>.(q</span></span>
<span class="line"><span>On April 7, 1998, Tim O&#39;Reilly held a meeting of key</span></span>
<span class="line"><span>leaders in the field. Announced in advance as the first</span></span>
<span class="line"><span>.q &quot;Freeware Summit,&quot;</span></span>
<span class="line"><span>by April 14 it was referred to as the first</span></span>
<span class="line"><span>.q &quot;Open Source Summit.&quot;</span></span>
<span class="line"><span>.)q</span></span></code></pre></div><h3 id="脚注" tabindex="-1">脚注 <a class="header-anchor" href="#脚注" aria-label="Permalink to “脚注”">​</a></h3><p>要插入脚注，请在脚注文本前后添加脚注宏（<code>.(f</code>），并使用内联宏（<code>\\**</code>）添加脚注标记。脚注标记应出现在文本中和脚注中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.pp</span></span>
<span class="line"><span>Christine Peterson recently wrote about open source:\\**</span></span>
<span class="line"><span>.(f</span></span>
<span class="line"><span>\\**Christine Peterson.</span></span>
<span class="line"><span>.q &quot;How I coined the term open source.&quot;</span></span>
<span class="line"><span>.i &quot;OpenSource.com.&quot;</span></span>
<span class="line"><span>1 Feb 2018.</span></span>
<span class="line"><span>.)f</span></span>
<span class="line"><span>.(q</span></span>
<span class="line"><span>On April 7, 1998, Tim O&#39;Reilly held a meeting of key</span></span>
<span class="line"><span>leaders in the field. Announced in advance as the first</span></span>
<span class="line"><span>.q &quot;Freeware Summit,&quot;</span></span>
<span class="line"><span>by April 14 it was referred to as the first</span></span>
<span class="line"><span>.q &quot;Open Source Summit.&quot;</span></span>
<span class="line"><span>.)q</span></span></code></pre></div><h3 id="封面" tabindex="-1">封面 <a class="header-anchor" href="#封面" aria-label="Permalink to “封面”">​</a></h3><p>大多数课程论文都需要一个包含论文标题，姓名和日期的封面。 在 <code>groff -me</code> 中创建封面需要一些组件。 我发现最简单的方法是使用居中的文本块并在标题、名字和日期之间添加额外的行。 （我倾向于在每一行之间使用两个空行）。在文章顶部，从标题页（<code>.tp</code>）宏开始，插入五个空白行（<code>.sp 5</code>），然后添加居中文本（<code>.(c</code>） 和额外的空白行（<code>.sp 2</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.tp</span></span>
<span class="line"><span>.sp 5</span></span>
<span class="line"><span>.(c</span></span>
<span class="line"><span>.b &quot;Writing Class Papers with groff -me&quot;</span></span>
<span class="line"><span>.)c</span></span>
<span class="line"><span>.sp 2</span></span>
<span class="line"><span>.(c</span></span>
<span class="line"><span>Jim Hall</span></span>
<span class="line"><span>.)c</span></span>
<span class="line"><span>.sp 2</span></span>
<span class="line"><span>.(c</span></span>
<span class="line"><span>February XX, 2018</span></span>
<span class="line"><span>.)c</span></span>
<span class="line"><span>.bp</span></span></code></pre></div><p>最后一个宏（<code>.bp</code>）告诉 groff 在标题页后添加一个分页符。</p><h3 id="更多内容" tabindex="-1">更多内容 <a class="header-anchor" href="#更多内容" aria-label="Permalink to “更多内容”">​</a></h3><p>这些是用 <code>groff-me</code> 写一份专业的论文非常基础的东西，包括前导和缩进段落，粗体和斜体，有序和无需列表，编号和不编号的章节标题，块引用以及脚注。</p>`,32)),a("p",null,[s[11]||(s[11]=n("我已经包含一个",-1)),p(e,{href:"https://opensource.com/sites/default/files/lorem-ipsum.me_.txt"},{default:i(()=>[...s[9]||(s[9]=[n("示例 groff 文件",-1)])]),_:1}),s[12]||(s[12]=n("来演示所有这些格式。 将 ",-1)),s[13]||(s[13]=a("code",null,"lorem-ipsum.me",-1)),s[14]||(s[14]=n(" 文件保存到您的系统并通过 groff 运行。 ",-1)),s[15]||(s[15]=a("code",null,"-Tps",-1)),s[16]||(s[16]=n(" 选项将输出类型设置为 ",-1)),s[17]||(s[17]=a("code",null,"PostScript",-1)),s[18]||(s[18]=n(" ，以便您可以将文档发送到打印机或使用 ",-1)),s[19]||(s[19]=a("code",null,"ps2pdf",-1)),s[20]||(s[20]=n(" 程序将其转换为 ",-1)),p(e,{href:"https://opensource.com/sites/default/files/lorem-ipsum.me_.pdf"},{default:i(()=>[...s[10]||(s[10]=[n("PDF 文件",-1)])]),_:1}),s[21]||(s[21]=n("。",-1))]),s[37]||(s[37]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>groff -Tps -me lorem-ipsum.me &gt; lorem-ipsum.me.ps</span></span>
<span class="line"><span>ps2pdf lorem-ipsum.me.ps lorem-ipsum.me.pdf</span></span></code></pre></div><p>如果你想使用 <code>groff -me</code> 的更多高级功能，请参阅 Eric Allman 所著的 “使用 Groff -me 来写论文”，你可以在你系统的 groff 的 <code>doc</code> 目录下找到一个名叫 <code>meintro.me</code> 的文件。这份文档非常完美的说明了如何使用 <code>groff-me</code> 宏来格式化你的论文。</p><hr>`,3)),a("p",null,[s[23]||(s[23]=n("via: ",-1)),p(e,{href:"https://opensource.com/article/18/2/how-format-academic-papers-linux-groff-me"},{default:i(()=>[...s[22]||(s[22]=[n("https://opensource.com/article/18/2/how-format-academic-papers-linux-groff-me",-1)])]),_:1})]),a("p",null,[s[27]||(s[27]=n("作者：",-1)),p(e,{href:"https://opensource.com/users/jim-hall"},{default:i(()=>[...s[24]||(s[24]=[n("Jim Hall",-1)])]),_:1}),s[28]||(s[28]=n(" 译者：",-1)),p(e,{href:"https://github.com/amwps290"},{default:i(()=>[...s[25]||(s[25]=[n("amwps290",-1)])]),_:1}),s[29]||(s[29]=n(" 校对：",-1)),p(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[26]||(s[26]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[32]||(s[32]=n("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[30]||(s[30]=[n("LCTT",-1)])]),_:1}),s[33]||(s[33]=n(" 原创编译，",-1)),p(e,{href:"https://linux.cn/"},{default:i(()=>[...s[31]||(s[31]=[n("Linux中国",-1)])]),_:1}),s[34]||(s[34]=n(" 荣誉推出",-1))])])}const C=o(c,[["render",f]]);export{y as __pageData,C as default};
